<div class="d-flex flex-wrap justify-content-between align-items-center mb-4"><div><p class="text-uppercase small fw-bold text-warning mb-1">Explore memories</p><h1 class="section-heading mb-1">Community gallery</h1><p class="text-muted mb-0">A collection of moments from our members.</p></div><div class="gallery-toolbar d-flex mt-3 mt-md-0"><div class="btn-group"><a class="btn btn-outline-dark <?=($style??'grid')==='grid'?'active':''?>" href="<?=url('photos?style=grid')?>">3-column</a><a class="btn btn-outline-dark <?=($style??'')==='list'?'active':''?>" href="<?=url('photos?style=list')?>">List cards</a><a class="btn btn-outline-dark" href="<?=url('photos?style=grid&sort=oldest')?>">Oldest</a></div></div></div><?php if(!$photos): ?><div class="empty-state"><i class="bi bi-images"></i><h3>No photos yet</h3><p>Be the first to share a memory.</p></div><?php else: ?><div class="row g-4 <?=($style??'grid')==='list'?'list-style':''?>"><?php foreach($photos as $photo): ?><div class="<?=($style??'grid')==='list'?'col-12':'col-sm-6 col-lg-4'?>"><article class="card photo-card h-100"><a href="<?=url('photo/'.$photo['id'])?>"><img src="<?=url('images/uploads/'.$photo['file_name'])?>" class="card-img-top" alt="<?=e($photo['title'])?>"></a><div class="card-body"><h5 class="card-title"><a class="text-decoration-none text-dark" href="<?=url('photo/'.$photo['id'])?>"><?=e($photo['title'])?></a></h5><p class="card-text text-muted small"><?=e($photo['description'])?></p><small>By <?=e($photo['author'])?> · <?=e($photo['date_time'])?></small></div></article></div><?php endforeach; ?></div><?php endif; ?>
